// hand:portmap/portmapv2
func codeMatch_hand_code_portmapv2_0(resp []byte) (r bool) {
	defer func() { recover() }()
	return len(resp) >= 8 && resp[0] == 0x80
}

// hand:bolt/bolt
func codeMatch_hand_code_bolt_0(resp []byte) (r bool) {
	defer func() { recover() }()
	if bytes.HasPrefix(resp, []byte{0x00, 0x00, 0x03, 0x04}) {
		return true
	}
	h := resp
	if len(h) > 16 {
		h = h[:16]
	}
	if bytes.Contains(h, []byte{0x60, 0x60, 0xb0, 0x17}) {
		return true
	}
	return bytes.Contains(resp, []byte("Memgraph.ExecutionException")) ||
		bytes.Contains(resp, []byte("Neo.ClientError")) ||
		bytes.Contains(resp, []byte("Neo.DatabaseError")) ||
		bytes.Contains(resp, []byte("Neo.TransientError"))
}

// hand:snmp/snmp
func codeMatch_hand_code_snmp_0(resp []byte) (r bool) {
	defer func() { recover() }()
	if len(resp) < 1 || resp[0] != 0x30 {
		return false
	}
	h := resp
	if len(h) > 64 {
		h = h[:64]
	}
	return bytes.Contains(h, []byte("public"))
}

// hand:ldap/ldap
func codeMatch_hand_code_ldap_0(resp []byte) (r bool) {
	defer func() { recover() }()
	if len(resp) >= 1 && resp[0] == 0x30 {
		if len(resp) >= 5 && resp[2] == 0x02 {
			idx := 4 + int(resp[3])
			if idx < len(resp) && resp[idx] >= 0x60 && resp[idx] <= 0x7f {
				return true
			}
		}
		h := resp
		if len(h) > 32 {
			h = h[:32]
		}
		for _, c := range h {
			if c == 0x61 {
				return true
			}
		}
	}
	return bytes.Contains(resp, []byte("1.3.6.1.4.1.1466.20036")) ||
		bytes.Contains(resp, []byte("unknown LDAP request")) ||
		bytes.Contains(resp, []byte("for an LDAP request"))
}

// hand:socks/socks5
func codeMatch_hand_code_socks5_0(resp []byte) (r bool) {
	defer func() { recover() }()
	return len(resp) >= 2 && len(resp) <= 8 && resp[0] == 0x05 && (resp[1] == 0x00 || resp[1] == 0xff)
}

