// hand:redis/redis
func codeMatch_hand_code_redis_0(resp []byte) (r bool) {
	defer func() { recover() }()
	if bytes.HasPrefix(resp, []byte("+PONG")) {
		return true
	}
	if bytes.Contains(resp, []byte("NOAUTH Authentication required")) {
		return true
	}
	if len(resp) >= 3 && resp[0] == '-' {
		i := 1
		for i < len(resp) && resp[i] >= 'A' && resp[i] <= 'Z' {
			i++
		}
		if i-1 >= 2 {
			return true
		}
	}
	return false
}

// hand:memcached/memcached
func codeMatch_hand_code_memcached_0(resp []byte) (r bool) {
	defer func() { recover() }()
	if bytes.HasPrefix(resp, []byte("ERROR\r\n")) ||
		bytes.HasPrefix(resp, []byte("STAT ")) ||
		bytes.HasPrefix(resp, []byte("VERSION ")) {
		return true
	}
	h := resp
	if len(h) > 64 {
		h = h[:64]
	}
	return bytes.Contains(h, []byte("CLIENT_ERROR")) || bytes.Contains(h, []byte("SERVER_ERROR"))
}

